# -*- coding: utf-8 -*-
"""
DeepSeek Harness —— 密码登录版 + Cloudflare 临时隧道 (Colab / Linux 用)

这个文件是仿照 ComfyUI 那个 Colab 脚本写的：
每个 `# @title` 段可以直接粘成一个 Colab 单元格（也可以直接 python 整个文件跑）。

它做的事情：
  1. 装 Node.js >= 22.19 与 pnpm
  2. 拉 deepseek-harness 源码，打上「-pwd 密码登录 + 首次来源 IP 绑定」补丁，然后构建
  3. 用 cloudflared 开一条 trycloudflare 临时隧道，把 127.0.0.1 上的 harness 暴露到公网

注意：构建整个 monorepo 很慢（十几分钟）而且吃内存，Colab 上请留足时间。
"""

